1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const LOYALTY_DISCOUNT_RATE = 0.2;
10	
11	const LOYALTY_THRESHOLD_YEARS = 2;
12	
13	const ITEM_BASE_PREMIUM: Record<string, number> = {
14	  sword: 100,
15	  amulet: 60,
16	  staff: 80,
17	  potion: 40,
18	  rune: 25,
19	  moonstone: 25,
20	};
21	
22	type Item = { type: string; cursed?: boolean; enchantment?: number };
23	
24	type Step = { op: string; items: Item[] };
25	
26	type Customer = { yearsWithMHPCO: number };
27	
28	type Scenario = { customer: Customer; steps: Step[] };
29	
30	const BLOCK_SIZE = 3;
31	
32	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
33	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
34	// a block either — "alike" means the same type, not the same family.
35	const BLOCK_BASE_PREMIUM = 60;
36	
37	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
38	
39	const countByType = (items: Item[]): Map<string, number> =>
40	  items.reduce(
41	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
42	    new Map<string, number>(),
43	  );
44	
45	const isBlock = (type: string, count: number): boolean =>
46	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
47	
48	const groupBasePremium = (type: string, count: number): number =>
49	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * ITEM_BASE_PREMIUM[type];
50	
51	const sum = (numbers: number[]): number =>
52	  numbers.reduce((total, value) => total + value, 0);
53	
54	const policyBasePremium = (items: Item[]): number =>
55	  sum(
56	    [...countByType(items)].map(([type, count]) =>
57	      groupBasePremium(type, count),
58	    ),
59	  );
60	
61	const CURSE_SURCHARGE_RATE = 0.5;
62	
63	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
64	
65	const HIGH_ENCHANTMENT_THRESHOLD = 5;
66	
67	const isCursed = (item: Item): boolean => item.cursed === true;
68	
69	const isHighlyEnchanted = (item: Item): boolean =>
70	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
71	
72	// Both surcharges can apply to the same item, so the rates add.
73	const itemSurchargeRate = (item: Item): number =>
74	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
75	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
76	
77	// Item-specific modifiers apply to the affected item's own base premium, not to
78	// the policy total — note that is the *ungrouped* base premium, so a cursed
79	// rune inside a block is surcharged on 25 G, not on a share of the block's 60.
80	const policyItemSurchargeTotal = (items: Item[]): number =>
81	  sum(
82	    items.map((item) => ITEM_BASE_PREMIUM[item.type] * itemSurchargeRate(item)),
83	  );
84	
85	const isLoyal = (customer: Customer): boolean =>
86	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
87	
88	// Policy-wide rates are summed rather than compounded, so a loyal customer's
89	// first insurance is levied at -20 % + 10 % = -10 % of the policy base premium.
90	const policyModifierRate = (customer: Customer): number =>
91	  (isLoyal(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
92	  FIRST_INSURANCE_SURCHARGE_RATE;
93	
94	// Deliberately additive, not `amount * (1 + rate)`: the latter is the same in
95	// exact arithmetic but not in binary floating point (100 * 1.1 is
96	// 110.00000000000001), and Math.ceil turns that 1e-14 into a whole gold piece.
97	const applyRate = (amount: number, rate: number): number =>
98	  amount + amount * rate;
99	
100	const quoteStep = (step: Step, customer: Customer): QuoteResult => {
101	  // Item-specific surcharges land here, before any policy-wide percentage
102	  // modifier — those are levied on the base premium including them.
103	  const baseAfterItemModifiers =
104	    policyBasePremium(step.items) + policyItemSurchargeTotal(step.items);
105	  const afterPercentageModifiers = applyRate(
106	    baseAfterItemModifiers,
107	    policyModifierRate(customer),
108	  );
109	
110	  // The fee is added after every percentage modifier, and only the final
111	  // premium is rounded — intermediates stay fractional.
112	  return { premium: Math.ceil(afterPercentageModifiers + PROCESSING_FEE) };
113	};
114	
115	export const runScenario = (scenario: Scenario): ScenarioResults => ({
116	  results: scenario.steps.map((step) => quoteStep(step, scenario.customer)),
117	});
